const body = $input.first().json.body || $input.first().json;

const url = (body.url || '').toString().trim();
const product = (body.product || '').toString().trim();
const cause = (body.cause || '').toString().trim();

if (!url) throw new Error('Missing "url".');
if (!product) throw new Error('Missing "product".');
if (!cause) throw new Error('Missing "cause".');

// URL sanity check.
// NOTE: n8n's Code-node sandbox does NOT expose the `URL` global, so parse manually.
const m = url.match(/^([a-z][a-z0-9+.\-]*):\/\/([^\/?#\s]+)([^\s]*)$/i);
if (!m) {
  throw new Error('"url" does not look like a valid URL (expected http://... or https://...): ' + url);
}
const protocol = m[1].toLowerCase();
if (protocol !== 'http' && protocol !== 'https') {
  throw new Error('Only http/https URLs are supported. Got: ' + protocol);
}
// strip any user:pass@ and :port to get the bare host
const hostname = m[2].split('@').pop().split(':')[0].toLowerCase();

const url_normalized = url.toLowerCase().replace(/\/+$/, '');
const product_normalized = product.toLowerCase().replace(/\s+/g, ' ');
const cause_normalized = cause.toLowerCase().replace(/\s+/g, ' ');
const cache_key = `${url_normalized.slice(0, 500)}|${product_normalized}|${cause_normalized}`;

return [{ json: { url, product, cause, hostname, protocol, url_normalized, product_normalized, cause_normalized, cache_key } }];

const norm = $('Normalize Input').first().json;
const rows = $input.all();
const row = (rows.length && rows[0].json && rows[0].json.cache_key) ? rows[0].json : null;

// A page's content rarely changes, so verifications stay valid longer than boycott status.
const FRESH_DAYS = 30;
let fresh = false;
if (row && row.checked_at) {
  const ageDays = (Date.now() - new Date(row.checked_at).getTime()) / 86400000;
  fresh = ageDays <= FRESH_DAYS;
}
return [{ json: { ...norm, cacheHit: !!row, fresh, cachedRow: row } }];

// Decide whether the link is genuinely usable, and score the DETERMINISTIC part of credibility.
const ctx = $('Evaluate Cache').first().json;
const resp = $input.first().json || {};

// --- pull content out of Tavily's response (defensively) ---
let content = '';
let failed = false;
let note = '';

if (resp.error) {
  failed = true;
  note = typeof resp.error === 'string' ? resp.error : JSON.stringify(resp.error);
}
if (Array.isArray(resp.results) && resp.results.length) {
  const r = resp.results[0];
  content = r.raw_content || r.rawContent || r.content || '';
}
if (Array.isArray(resp.failed_results) && resp.failed_results.length) {
  failed = true;
  note = resp.failed_results[0].error || 'extraction failed';
}

content = (content || '').toString().trim();
const content_length = content.length;

// A page that returns almost nothing (paywall, JS-only, 404 page) is not verifiable.
const available = !failed && content_length >= 200;
if (!available && !note) {
  note = content_length > 0
    ? `page returned only ${content_length} characters (paywall, JS-only page, or empty)`
    : 'no readable content returned';
}

// --- domain + metadata signals (deterministic credibility base) ---
// hostname/protocol were parsed once in Normalize Input (no `URL` global in this sandbox)
const domain = (ctx.hostname || '').replace(/^www\./, '').toLowerCase();
const isHttps = ctx.protocol === 'https';

const MAJOR_NEWS = ['reuters.com','apnews.com','bbc.com','bbc.co.uk','aljazeera.com','theguardian.com','nytimes.com','washingtonpost.com','ft.com','bloomberg.com','cnn.com','npr.org','economist.com','wsj.com','lemonde.fr','dw.com','france24.com','abcnews.go.com','cbsnews.com','nbcnews.com','independent.co.uk','telegraph.co.uk','haaretz.com','middleeasteye.net','thenational.ae','timesofindia.indiatimes.com','scmp.com'];
const NGO_WATCHDOG = ['hrw.org','amnesty.org','transparency.org','oxfam.org','greenpeace.org','globalwitness.org','cleanclothes.org','business-humanrights.org','somo.nl'];
const ADVOCACY     = ['bdsmovement.net','ethicalconsumer.org','boycott.thewitness.org','sumofus.org'];
const REFERENCE    = ['wikipedia.org','britannica.com'];
const BLOG_HOSTS   = ['medium.com','substack.com','blogspot.com','wordpress.com','tumblr.com','blogger.com'];
const SOCIAL       = ['x.com','twitter.com','facebook.com','reddit.com','tiktok.com','instagram.com','youtube.com','threads.net','t.me','linkedin.com'];

const hits = (list) => list.some(d => domain === d || domain.endsWith('.' + d));
const isOfficialTld = /\.(gov|edu|int)$/.test(domain) || /\.gov\.[a-z]{2}$/.test(domain) || /\.ac\.[a-z]{2}$/.test(domain) || ['un.org','who.int','europa.eu','ilo.org'].some(d => domain === d || domain.endsWith('.' + d));

let domain_tier, domain_score;
if (isOfficialTld)          { domain_tier = 'official';   domain_score = 40; }
else if (hits(MAJOR_NEWS))  { domain_tier = 'major_news'; domain_score = 40; }
else if (hits(NGO_WATCHDOG)){ domain_tier = 'ngo';        domain_score = 35; }
else if (hits(ADVOCACY))    { domain_tier = 'advocacy';   domain_score = 28; }
else if (hits(REFERENCE))   { domain_tier = 'reference';  domain_score = 25; }
else if (hits(BLOG_HOSTS))  { domain_tier = 'blog';       domain_score = 12; }
else if (hits(SOCIAL))      { domain_tier = 'social';     domain_score = 8;  }
else                        { domain_tier = 'unknown';    domain_score = 20; }

// heuristic metadata detection on the extracted text
const head = content.slice(0, 3000);
const has_author = /\b(by|By|BY)\s+[A-Z][a-z]+\s+[A-Z][a-z']+/.test(head) || /author/i.test(head);
const has_date = /\b(20\d{2}-\d{2}-\d{2})\b/.test(head) ||
  /\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+20\d{2}\b/i.test(head) ||
  /\b\d{1,2}\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s+20\d{2}\b/i.test(head);

let credibility_base = domain_score;
if (has_author) credibility_base += 8;
if (has_date) credibility_base += 8;
if (isHttps) credibility_base += 4;
if (content_length >= 1200) credibility_base += 10;
credibility_base = Math.max(0, Math.min(70, credibility_base)); // base caps at 70; LLM can add up to +15

return [{ json: {
  ...ctx,
  available,
  availability_note: available ? '' : note,
  content,
  content_length,
  domain,
  signals: { domain_tier, domain_score, has_author, has_date, isHttps, content_length },
  credibility_base
} }];

// Parse the model's JSON, VALIDATE its quotes against the real page, then score deterministically.
const ctx = $('Build LLM Context').first().json;
const resp = $input.first().json;

let content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  // some models wrap JSON in prose or fences — try to salvage the object
  const m = String(content).match(/\{[\s\S]*\}/);
  try { parsed = JSON.parse(m ? m[0] : '{}'); } catch (e2) { parsed = {}; }
}

const support = ['supports','partial','unrelated','contradicts'].includes(parsed.support) ? parsed.support : 'unrelated';
const mentions_product = parsed.mentions_product === true;
const mentions_cause = parsed.mentions_cause === true;

// --- anti-hallucination: keep only quotes that actually appear in the page ---
const pageLower = (ctx.content || '').toLowerCase().replace(/\s+/g, ' ');
const rawEvidence = Array.isArray(parsed.evidence) ? parsed.evidence : [];
const evidence = rawEvidence
  .filter(q => typeof q === 'string' && q.trim().length > 10)
  .map(q => q.trim())
  .filter(q => {
    const probe = q.toLowerCase().replace(/\s+/g, ' ').slice(0, 60);
    return pageLower.includes(probe);
  })
  .slice(0, 3);
const evidence_dropped = rawEvidence.length - evidence.length;

// --- support strength (deterministic) ---
let support_strength;
if (support === 'supports')         support_strength = 80 + evidence.length * 5;
else if (support === 'partial')     support_strength = 45 + evidence.length * 3;
else if (support === 'contradicts') support_strength = 0;
else                                support_strength = 5;

if (!mentions_product)      support_strength = Math.min(support_strength, 10);
else if (!mentions_cause)   support_strength = Math.min(support_strength, 35);
if (support === 'supports' && evidence.length === 0) support_strength = Math.min(support_strength, 60); // claimed support but no verifiable quote
support_strength = Math.max(0, Math.min(100, Math.round(support_strength)));

// --- credibility: deterministic base + bounded LLM adjustment ---
let adjust = Number(parsed.credibility_adjustment);
if (!Number.isFinite(adjust)) adjust = 0;
adjust = Math.max(-15, Math.min(15, Math.round(adjust)));
const credibility = Math.max(0, Math.min(100, (ctx.credibility_base || 0) + adjust));

// --- overall verdict ---
let verdict;
if (support === 'contradicts')      verdict = 'contradicts_claim';
else if (!mentions_product)         verdict = 'unrelated';
else if (support_strength >= 70)    verdict = 'verified';
else if (support_strength >= 40)    verdict = 'weak_support';
else                                verdict = 'unrelated';

const s = ctx.signals || {};
const notes = [
  `Support strength ${support_strength}/100 = how strongly THIS page backs "${ctx.product}" + "${ctx.cause}" (from the model's classification, capped by whether the product and cause are actually discussed, and by how many quotes were verifiable).`,
  `Credibility ${credibility}/100 = deterministic base ${ctx.credibility_base} (domain tier: ${s.domain_tier}, author: ${!!s.has_author}, date: ${!!s.has_date}, length: ${s.content_length}) adjusted by ${adjust >= 0 ? '+' : ''}${adjust} from the model.`,
  evidence_dropped > 0 ? `${evidence_dropped} quote(s) were discarded because they could not be found verbatim in the page.` : '',
  'These scores describe THIS ONE LINK, not whether the boycott claim is true overall.'
].filter(Boolean).join(' ');

return [{ json: {
  url: ctx.url,
  product: ctx.product,
  cause: ctx.cause,
  cache_key: ctx.cache_key,
  available: true,
  availability_note: '',
  domain: ctx.domain,
  content_length: ctx.content_length,
  verdict,
  support_strength,
  credibility,
  credibility_base: ctx.credibility_base,
  credibility_adjust: adjust,
  credibility_reason: (parsed.credibility_reason || '').toString().slice(0, 500),
  mentions_product,
  mentions_cause,
  content_type: (parsed.content_type || 'other').toString(),
  summary: (parsed.summary || '').toString().slice(0, 1000),
  evidence,
  evidence_dropped,
  notes,
  checked_at: new Date().toISOString(),
  served_from: 'live'
} }];

// One slim, stable response shape. Add "detail": true (body) or ?detail=1 (query) for every field.
const wh = $('Webhook (POST /verify-link)').first().json;
const q = wh.query || {};
const b = wh.body || {};
const flag = String(q.detail !== undefined ? q.detail : (b.detail !== undefined ? b.detail : '')).toLowerCase();
const wantsDetail = flag === '1' || flag === 'true' || flag === 'yes';

const f = $json;
const slim = {
  url: f.url,
  product: f.product,
  cause: f.cause,
  verdict: f.verdict,                      // verified | weak_support | unrelated | contradicts_claim | unreachable
  support_strength: f.support_strength,    // 0-100, does THIS page back THIS product + THIS cause
  credibility: f.credibility,              // 0-100, is the source worth anything
  summary: f.summary || f.availability_note || '',
  evidence: f.evidence || [],              // verbatim quotes, already checked against the page
  checked_at: f.checked_at,
  served_from: f.served_from,
};

return [{ json: wantsDetail ? f : slim }];
